    "settings.diagnostics.providerRequestTrace.actionFailed": "L’opération n’a pas abouti",
    "settings.diagnostics.providerRequestTrace.description": "Une fois activé, la requête finale envoyée et chaque nouvelle tentative physique d’une même requête logique au Provider sont enregistrées dans un groupe, avec les métadonnées de réponse, les octets bruts de réponse avant analyse, les limites de chunks ou de trames WebSocket et l’issue en échec. Le répertoire temp/provider-api-trace de la session propriétaire alterne entre quatre emplacements de requêtes logiques ; chaque tentative conserve jusqu’à 64 Mio de données de réponse brutes, y compris les octets reçus avant un échec ou une annulation manuelle. Les tâches Batch d’embeddings VCE conservent aussi les fichiers de requête exacts et les fichiers output/error complets du Provider sous l’arborescence temp/vce du répertoire de données de l’application, séparés par projet et par tâche, sans rotation automatique. Les fichiers peuvent contenir des prompts, du code source, des arguments et résultats d’outils ainsi que la sortie du Provider ; n’activez cette option que pendant le diagnostic d’un problème.",
